"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["96618"],{69755(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fase_canonica.unidade_sugerida_nao_encontrada","status":422,"titulo":"Unidade sugerida da fase can\xf4nica n\xe3o encontrada ou n\xe3o est\xe1 mais viva"},"descricao":{"codigo":"uniplus.configuracao.fase_canonica.unidade_sugerida_nao_encontrada","requisitos":[],"oQueAconteceu":["O campo `unidadeSugeridaId` n\xe3o corresponde a nenhuma unidade da Unifesspa **viva**: o identificador n\xe3o existe, ou a unidade foi removida. A unidade sugerida \xe9 opcional e orientativa: indica qual unidade costuma responder pela fase, mas o processo seletivo define a unidade respons\xe1vel na sua pr\xf3pria configura\xe7\xe3o. A resposta aponta o campo `unidadeSugeridaId` em `errors[]`. Nada foi gravado.","**Na cria\xe7\xe3o**, o campo \xe9 conferido depois das demais confer\xeancias da fase (a fase s\xf3 chega a esta etapa com os outros campos v\xe1lidos), e omiti-lo cria a fase sem unidade sugerida.","**Na atualiza\xe7\xe3o**, a fase \xe9 procurada antes (com identificador inexistente a resposta \xe9 [fase can\xf4nica n\xe3o encontrada](/erros/uniplus.configuracao.fase_canonica.nao_encontrada)) e as coer\xeancias dos campos s\xe3o conferidas antes da unidade. A atualiza\xe7\xe3o substitui a sugest\xe3o por inteiro: o valor enviado \xe9 comparado com o j\xe1 gravado, e s\xf3 uma troca \xe9 conferida. Reenviar o identificador que j\xe1 est\xe1 gravado preserva a sugest\xe3o, mesmo que a unidade tenha sido removida depois. **Omitir o campo, ou envi\xe1-lo nulo, remove a sugest\xe3o existente.**"],"comoResolver":["Informe em `unidadeSugeridaId` o identificador de uma unidade da Unifesspa existente na listagem de unidades.","- **Cria\xe7\xe3o:** omita o campo se a fase n\xe3o tem unidade sugerida.\\n- **Atualiza\xe7\xe3o:** para manter a sugest\xe3o atual, reenvie o identificador j\xe1 gravado; para troc\xe1-la, envie o de uma unidade viva; para retir\xe1-la, omita o campo ou envie nulo. Omitir o campo sem querer remove a sugest\xe3o."],"ondeAparece":["Cria\xe7\xe3o de uma fase can\xf4nica (POST /api/configuracao/admin/fases-canonicas), depois de as demais confer\xeancias da fase","Atualiza\xe7\xe3o de uma fase can\xf4nica (PUT /api/configuracao/admin/fases-canonicas/`{id}`), depois de a fase ser encontrada e quando a unidade sugerida enviada \xe9 diferente da gravada"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fase canonica"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);